// ── STAR story validator — surfaces the four most common weaknesses ──
function validateSTAR(story) {
  const issues = [];

  // Situation: needs real context, not one line
  if (!story.situation || story.situation.split(' ').length < 15)
    issues.push('Situation too thin — add team size, project scale, and stakes.');

  // Task: must be YOUR responsibility, not the team\'s
  const taskLower = (story.task || '').toLowerCase();
  if (!taskLower.includes('i ') && !taskLower.startsWith('i '))
    issues.push('Task lacks first-person ownership — use "I was responsible for..."');

  // Action: must be substantial and include a decision point
  const actionWords = (story.action || '').split(' ').length;
  if (actionWords < 50)
    issues.push('Action too short — explain step-by-step reasoning and decision point.');
  if (!story.action || !/because|chose|decided|instead|rather than/i.test(story.action))
    issues.push('Action lacks a decision rationale — add why you chose this path.');

  // Result: must contain at least one number
  if (!story.result || !/\d/.test(story.result))
    issues.push('Result lacks numbers — add %, $, latency, time saved, or user count.');

  return issues.length === 0
    ? { valid: true, message: 'Story is structurally solid.' }
    : { valid: false, issues };
}

// Weak story — fails four checks
const weak = {
  situation: 'We had a project with a deadline.',
  task: 'The team needed to finish on time.',
  action: 'We worked together and figured it out.',
  result: 'It went well and everyone was happy.',
};
console.log(validateSTAR(weak));
// { valid: false, issues: [
//   'Situation too thin...',
//   'Task lacks first-person ownership...',
//   'Action too short...',
//   'Action lacks a decision rationale...',
//   'Result lacks numbers...' ]}

// Strong story — passes all checks
const strong = {
  situation: 'At Acme Corp, our three-person backend team owned a payment API ' +
    'serving 200K daily transactions. Six weeks before the holiday peak, ' +
    'a performance regression appeared that we had missed in staging.',
  task: 'I was the on-call engineer that week, responsible for diagnosing ' +
    'the root cause and shipping a fix without taking the API offline.',
  action: 'I profiled the hot path with Node\'s built-in profiler to rule out ' +
    'application code. Then I examined recent query execution plans — a deploy ' +
    'three days earlier had introduced a query on order_status with no supporting ' +
    'index, causing a full-table scan on every checkout. I chose to add the index ' +
    'rather than rewrite the query because the query logic was correct. I used ' +
    'CREATE INDEX CONCURRENTLY to avoid table locks and timed the migration at ' +
    'the lowest-traffic window of the day.',
  result: 'P95 latency dropped from 1.2s to 180ms — an 85% reduction. We handled ' +
    'the holiday traffic peak without any downtime. I then added a query-plan ' +
    'regression check to CI so this class of missing index cannot ship silently.',
};
console.log(validateSTAR(strong)); // { valid: true, message: 'Story is structurally solid.' }

// ── Red flag pattern detector — common anti-patterns in STAR stories ──
const redFlags = [
  {
    id: 'we-language',
    description: 'Using "we" throughout the Action section',
    badExample: 'We decided to refactor the service and we deployed it to production.',
    goodExample:
      'I proposed the refactor in sprint planning, drafted the migration plan, ' +
      'coordinated with the QA team, and led the two-day implementation sprint.',
    fix: 'Replace every "we" with the specific action you personally took.',
  },
  {
    id: 'no-quantified-result',
    description: 'Vague result without numbers',
    badExample: 'The project was a success and the team was really happy.',
    goodExample:
      'Delivery time dropped from 12 days to 4 days — a 67% reduction. ' +
      'Customer NPS for that flow rose 18 points over the following quarter.',
    fix: 'Always include at least one before/after metric, business outcome, or dollar value.',
  },
  {
    id: 'blaming-others',
    description: 'Villain-framing in conflict stories',
    badExample: 'My manager was wrong and I had to work around their bad decision.',
    goodExample:
      'My manager prioritized the deadline; I prioritized long-term scalability. ' +
      'Both views were legitimate. I scheduled a 1:1, shared my load test data, ' +
      'and we aligned on a phased approach: ship now with a documented capacity limit, ' +
      'redesign next sprint.',
    fix: 'Make both sides sound reasonable. Show collaboration, not victory.',
  },
  {
    id: 'no-tension',
    description: 'Story has no genuine obstacle or decision point',
    badExample: 'I was assigned a feature, built it in two weeks, and shipped it on time.',
    goodExample:
      'Halfway through, the third-party payment API we depended on deprecated ' +
      'our endpoint with 48 hours notice. I had to find an alternative, migrate ' +
      'the data pipeline, rerun test coverage, and coordinate a hotfix deploy — all ' +
      'without slipping the customer launch date.',
    fix: 'Include the moment where the outcome was genuinely in doubt.',
  },
  {
    id: 'fake-weakness',
    description: 'Deflecting the failure question with a disguised strength',
    badExample: 'I am a perfectionist — I sometimes over-polish code.',
    goodExample:
      'I shipped a feature without sufficient load testing. It caused a 20-minute ' +
      'outage on launch day. I immediately set up an incident channel, communicated ' +
      'status every 10 minutes, and rolled back within the hour. I then added load ' +
      'testing to our CD pipeline as a mandatory gate.',
    fix: 'Own a real mistake. Describe the impact. Show what you changed.',
  },
];

redFlags.forEach(({ id, description, fix }) => {
  console.log(`[${id}] ${description}`);
  console.log(`  Fix: ${fix}`);
});
// Prints all five red flag patterns with fixes
